/**
 * Inheritors API - 传承人接口
 * 
 * 接口列表:
 * - getInheritors: 获取所有传承人 (支持筛选)
 * - getInheritorDetail: 获取单个传承人详情
 */

import request from './request.js'

export default {
  /**
   * 获取所有传承人
   * @param {object} params - 查询参数 { specialty, level, region, search, page, limit }
   */
  getInheritors(params = {}) {
    return request.get('/inheritors', { params })
  },

  /**
   * 获取单个传承人详情
   * @param {string} id - 传承人ID
   */
  getInheritorDetail(id) {
    return request.get(`/inheritors/${id}`)
  }
}
